 The set of real-valued BV functions is defined as
\begin{align}
	\mathsf{BV}(U)\coloneqq \set{v\in L^1(U)}{V(v;U)<\infty}\,.

Using these facts, for any real $s$ and $t$ and natural numbers $J$ and $K$, we define the orthogonal projection operator (tensor) $\Pi_{JK}\in \mathscr{L}(\mathrm{HS}(H^s_\diamond({\partial\Omega});H^t({\partial\Omega})/\mathbb{C}))$ by
\begin{align}\label{eqn:projection_operator}
    T\mapsto \Pi_{JK}T\coloneqq \sum_{j=1}^{J}\sum_{k=1}^K\iptemp{T \varphi_k^{(s)}}{\varphi_j^{(t)}}_{H^t({\partial\Omega})}\,
    \varphi_j^{(t)}\otimes_{H^s({\partial\Omega})}\varphi_k^{(s)}\,.
\end{align}

Moreover, the NtD map $\mathscr{R}_{\gamma}$ is defined (in the trace sense) by
\begin{equation}\label{eqn:ntd}
	g\mapsto \mathscr{R}_{\gamma} g \coloneqq u_{\gamma,g}\big|_{{\partial\Omega}}
\end{equation}
and satisfies $ \mathscr{R}_{\gamma} \in \mathscr{L}(H_\diamond^{-1/2}({\partial\Omega});H_{\phantom{\diamond}}^{1/2}({\partial\Omega})/\mathbb{C})$.

Define sets
\begin{align}\label{eqn:conductivity_set_prelim}
    \begin{split}
        \Gamma &\coloneqq \set{\gamma\in L^\infty(\Omega;\mathbb{R})}{m\leq \gamma(x)\leq M \,\ \text{for a.e.} \,\ x\in\Omega}\quad\text{and}\quad\\
      \Gamma' &\coloneqq \set{\gamma\in\Gamma}{\gamma = \mathds{1} \,\ \text{a.e. on} \,\ \Omega\setminus\Omega' }
        \,.
    \end{split}
\end{align}

We establish a $L^2(\Omega)$ continuity result when $d=2$ that is a consequence of \cite[Thm.~1.6, pp.~5661--5662]{faraco2018characterization}. It relies on the notion of integral modulus of continuity. To this end, for any $p\in [1,\infty)$, the integral $p$-modulus of continuity of any $v\colon\mathbb{R}^d\to\mathbb{R}$ is the function $\omega^{(p)}(v)\colon \mathbb{R}_{\geq 0}\to\mathbb{R}_{\geq 0}$ defined for $t\geq 0$ by
\begin{align}\label{eqn:modulus_sup}
    \omega^{(p)}(v)(t)\coloneqq \sup_{\abstemp{y}\leq t}\normtemp{\tau_y v - v}_{L^p(\mathbb{R}^d)}\,.
\end{align}
In \eqref{eqn:modulus_sup}, $\tau_y$ is the translation-by-$y$ operator $(\tau_yv)(x)\coloneqq v(x+y)$ for fixed $y\in\mathbb{R}^d\setminus\{0\}$ and for any $x\in\mathbb{R}^d$. We often invoke \eqref{eqn:modulus_sup} with $v$ equal to the continuous extension $\widetilde{\gamma}\colon \mathbb{R}^d\to\mathbb{R}_{\geq 0}$ of $\gamma\in\mathcal{X}_d(R)$ defined by $\widetilde{\gamma} = \gamma$ on $\Omega$ and $\widetilde{\gamma}\equiv 1$ on $\mathbb{R}^d\setminus\Omega$.

\label{thm:stability}
    Let $d\geq 2$. Suppose that $\alpha\in(0,1)$ and $R>0$ are as in \eqref{eqn:conductivity_set}. Then there exist constants $C>0$, $\rho>0$, and $t_0\in (0,1)$ depending on $d$, $\alpha$, $M$, $m$, $R$, $\Omega$, and $\Omega'$ such that for any $\gamma\in\mathcal{X}_d(R)$ and any $\gamma_0\in\mathcal{X}_d(R)$ with $\mathcal{X}_d(R)$ as in \eqref{eqn:conductivity_set}, the DtN maps $\Lambda_{\gamma}$ and $\Lambda_{\gamma_0}$ satisfy
    \begin{align}\label{eqn:stability_log}
        \normtemp{\gamma-\gamma_0}_{L^2(\Omega)} \leq C \omega\Bigl(\normtemp{\Lambda_{\gamma} - \Lambda_{\gamma_0}}_{\mathscr{L}\mathopen{}\mathclose\bgroup\originalleft(H^{1/2}({\partial\Omega})/\mathbb{C};H^{-1/2}({\partial\Omega})\aftergroup\egroup\originalright)}\Bigr)\,,
    \end{align}
    where the modulus of continuity $\omega\colon \mathbb{R}_{>0}\to\mathbb{R}_{>0}$ is given by
    \begin{align}\label{eqn:modulus_log}
        t\mapsto \omega(t)\coloneqq \log\mathopen{}\mathclose\bgroup\originalleft(\frac{1}{\min(t,t_0)}\aftergroup\egroup\originalright)^{-\rho}\,. 
    \end{align}

First, $\Lambda_{\gamma}\mathds{1} =\Lambda_{\gamma_0}\mathds{1} =0$ for any $(\gamma,\gamma_0)\in\Gamma\times\Gamma$ implies that
\begin{align*}
    \normtemp{\Lambda_{\gamma} - \Lambda_{\gamma_0}}_{\mathscr{L}\mathopen{}\mathclose\bgroup\originalleft(H^{1/2}({\partial\Omega})/\mathbb{C};H^{-1/2}({\partial\Omega})\aftergroup\egroup\originalright)} =  \normtemp{\Lambda_{\gamma} - \Lambda_{\gamma_0}}_{\mathscr{L}\mathopen{}\mathclose\bgroup\originalleft(H^{1/2}({\partial\Omega});H^{-1/2}({\partial\Omega})\aftergroup\egroup\originalright)}\,.
\end{align*}
Thus, it suffices to develop the stability results for the rightmost operator norm. We denote this norm by $\normtemp{{\,\cdot\,}}$ in the remainder of the proof. 

We begin with the $d=2$ case. Let $B \coloneqq \max\{1, M,m^{-1}\}\geq 1$. Notice that $\gamma\in\mathcal{X}_2(R)$ implies $B^{-1}\leq\widetilde{\gamma}(x)\leq B$ for a.e. $x\in\mathbb{R}^2$. Fix $p=p_B > 2B\geq 2$ and $\gamma\in\mathcal{X}_2(R)$. 
The asserted result will follow by \cite[Thm.~1.6, pp.~5661--5662]{faraco2018characterization} if there exists a so-called uniform modulus of continuity $\omega_0$ such that $\sup_{\gamma\in\mathcal{X}_2(R)} \omega^{(p)}(\widetilde{\gamma})(t)\leq \omega_0(t)$ for every $t\geq 0$. To show this, we invoke properties of BV functions. For any $y\in\mathbb{R}^2$, by H\"older's inequality and the triangle inequality we compute
\begin{align*}
    \normtemp{\tau_y \widetilde{\gamma} - \widetilde{\gamma}}_{L^{p}(\mathbb{R}^2)}&=\biggl(\int_{\mathbb{R}^2}\abstemp{\widetilde{\gamma}(x+y)-\widetilde{\gamma}(x)}^{p-1} \abstemp{\widetilde{\gamma}(x+y)-\widetilde{\gamma}(x)} \dd{x}\biggr)^{1/p}\\
    &\leq \normtemp[\big]{\tau_y \widetilde{\gamma} - \widetilde{\gamma}}_{L^{\infty}(\mathbb{R}^2)}^{(p-1)/p}\normtemp[\big]{\tau_y \widetilde{\gamma} - \widetilde{\gamma}}_{L^{1}(\mathbb{R}^2)}^{1/p}\\
    &\leq (2B)^{(p-1)/p}\normtemp[\big]{\tau_y \widetilde{\gamma} - \widetilde{\gamma}}_{L^{1}(\mathbb{R}^2)}^{1/p}\,.
\end{align*}
By \cref{lem:tv_identity} and the definitions of $\mathcal{X}_2(R)$, BV, and total variation, it holds that $V(\widetilde{\gamma};\mathbb{R}^2)=V(\gamma;\Omega)<\infty$ and $\widetilde{\gamma}\in L^1_{\mathrm{loc}}(\mathbb{R}^2)$ for any $\gamma\in\mathcal{X}_2(R)$. Application of \cite[Exercise~14.3(ii), p. 460]{leoni2017first}, \cite[Exercise~14.3(i), p. 460]{leoni2017first}, and \cite[Lemma~14.37, p.~483]{leoni2017first}, in that order, delivers the estimate
\begin{align*}
    \normtemp{\tau_y \widetilde{\gamma} - \widetilde{\gamma}}_{L^{1}(\mathbb{R}^2)}\leq  V(\widetilde{\gamma};\mathbb{R}^2)\abstemp{y}= V(\gamma;\Omega) \abstemp{y}\leq R \abstemp{y}
\end{align*}
on $\mathcal{X}_2(R)$. For every $t\geq 0$, we deduce that
\begin{align*}
    \sup_{\gamma\in\mathcal{X}_2(R)} \omega^{(p)}(\widetilde{\gamma})(t)=\sup_{\gamma\in\mathcal{X}_2(R)} \sup_{\abstemp{y}\leq t}\normtemp{\tau_y \widetilde{\gamma} - \widetilde{\gamma}}_{L^{p}(\mathbb{R}^2)}\leq \bigl((2B)^{(p-1)/p}R^{1/p}\bigr) t^{1/p}\,.
\end{align*}
Thus, with $C_{B,R}$ the rightmost constant in the preceding display, 
the map $\omega_0\colon t\mapsto C_{B,R}\, t^{1/p_B}$ is a valid uniform modulus of continuity. In particular, $\omega_0$ is continuous on $\mathbb{R}_{>0}$ and hence upper semi-continuous. Then \cite[p.~5662]{faraco2018characterization} implies that \eqref{eqn:stability_log} is valid with modulus of continuity $\omega$ in \eqref{eqn:modulus_log} for some $\rho=\rho_2$ and $t_0=t_0^{(2)}$.

Now let $d\geq 3$. We exploit the stronger \emph{a priori} bounds on the conductivities in the set $\mathcal{X}_d(R)$. Define $b=\max\{1, m^{-1}, R\}$. For $\gamma\in\mathcal{X}_d(R)$, we have $\gamma(x)\geq m^{-1}\geq b^{-1}$ for all $x\in \Omega$ and $\normtemp{\gamma}_{C^{1,\alpha}}\leq R\leq b$. Then \cite[Thm.~1.1, p.~470]{caro2013stability} delivers the stability bound $\normtemp{\gamma-\gamma_0}_{L^\infty(\Omega)} \leq C \omega'(\normtemp{\Lambda_{\gamma} - \Lambda_{\gamma_0}})$ on $\mathcal{X}_d(R)$, where $\omega'(t)=(\log(\min(t, t_0^{(d)})^{-1}))^{-\rho_d}$ for some $\rho_d\in(0,1)$ depending only on $d$ and $\alpha$. Here, the value of $t_0^{(d)}\in(0,1)$ is implied by \cite[pp.~489--490]{caro2013stability}. To complete the proof, we use the continuous embedding $L^\infty\hookrightarrow L^2$, enlarge $C$, and choose $\rho\coloneqq \min(\rho_2,\rho_d)$ and $t_0\coloneqq \max(t_0^{(2)}, t_0^{(d)})$ to ensure that \eqref{eqn:stability_log} and \eqref{eqn:modulus_log} are valid for all $d\geq 2$.

\label{lem:ntd_to_dtn}
    There exists a constant $C>0$ depending on $d$, $\Omega$, $m$, and $M$ such that for any $\gamma\in\Gamma$ and $\gamma_0\in \Gamma$ with $\Gamma$ as in \eqref{eqn:conductivity_set_prelim}, it holds that
    \begin{align}\label{eqn:ntd_to_dtn}
         \normtemp[\big]{\Lambda_{\gamma} - \Lambda_{\gamma_0}}_{\mathscr{L}(H^{1/2}({\partial\Omega})/\mathbb{C};H^{-1/2}({\partial\Omega}))} \leq C \normtemp[\big]{\mathscr{R}_{\gamma}-\mathscr{R}_{\gamma_0}}_{\mathscr{L}(H^{-1/2}_\diamond({\partial\Omega});H_{\phantom{\diamond}}^{1/2}({\partial\Omega})/\mathbb{C})}\,.
    \end{align}

\label{lem:ntd_unif_op}
    For any $s\in\mathbb{R}$ and any $t\in\mathbb{R}$, there exist $C_s>0$ and $C_{s,t}'>0$ depending on $s$ and $t$ such that
    \begin{align}\label{eqn:ntd_unif_op}
        \begin{split}
            \sup_{\gamma\in\Gamma'}\normtemp{\mathscr{R}_{\gamma}}_{\mathscr{L}({H}_\diamond^s({\partial\Omega});H^{s+1}({\partial\Omega})/\mathbb{C})}&\leq C_s \quad\text{and}\quad\\
            \sup_{\gamma\in\Gamma'}\normtemp{\mathscr{R}_{\gamma} - \mathscr{R}_{\mathds{1}}}_{\mathscr{L}({H}_\diamond^s({\partial\Omega});H^{t}({\partial\Omega})/\mathbb{C})}&\leq C_{s,t}'\,.
        \end{split}
    \end{align}

\label{lem:hs_to_op}
    For any real numbers $s$ and $t$, there exists $C>0$ depending on $d$, $s$, $t$, $\Omega$, $\Omega'$, $m$, and $M$ such that for all $\gamma$ and $\gamma_0$ belonging to $\Gamma'$, it holds that
    \begin{align}\label{eqn:hs_to_op}
        \normtemp[\big]{\mathscr{R}_{\gamma}-\mathscr{R}_{\gamma_0}}_{\mathscr{L}(H^{-1/2}_\diamond({\partial\Omega});H_{\phantom{\diamond}}^{1/2}({\partial\Omega})/\mathbb{C})}\leq C\normtemp[\big]{\mathscr{R}_{\gamma}-\mathscr{R}_{\gamma_0}}^{1/2}_{\mathrm{HS}(H^{s}_\diamond({\partial\Omega});H^{t}({\partial\Omega})/\mathbb{C})}\,.
    \end{align}

The following argument mimics the proof of \cite[Lemma~5, p.~177]{abraham2019statistical} for a similar result applicable to DtN maps instead of NtD maps. Let $\gamma\in\Gamma'$ and $\gamma_0\in\Gamma'$ be arbitrary. We make use of low-rank approximations and the extreme smoothing properties of the shifted NtD maps $\widetilde{\mathscr{R}}_{\gamma}\coloneqq \mathscr{R}_{\gamma}-\mathscr{R}_{\mathds{1}}$ and $\widetilde{\mathscr{R}}_{\gamma_0}\coloneqq \mathscr{R}_{\gamma_0} - \mathscr{R}_{\mathds{1}}$.
Write $\normtemp{{\,\cdot\,}}$ for the $\mathrm{HS}(H_\diamond^{-1/2}({\partial\Omega});H^{1/2}({\partial\Omega})/\mathbb{C})$ operator norm. To begin, we project onto finite-dimensional subspaces via $P_J=\Pi_{JJ}$ from \eqref{eqn:projection_operator}. For any $J$, this leads to
\begin{align*}
    \normtemp{\mathscr{R}_{\gamma}-\mathscr{R}_{\gamma_0}}_{\mathscr{L}(H_\diamond^{-1/2};H_{\phantom{\diamond}}^{1/2}/\mathbb{C})}&\leq \normtemp{\mathscr{R}_{\gamma}-{\mathscr{R}}_{\gamma_0}}\\
    &=\normtemp{{\widetilde{\mathscr{R}}_{\gamma}} - {\widetilde{\mathscr{R}}_{\gamma_0}}}\\
    &\leq \normtemp{{\widetilde{\mathscr{R}}_{\gamma}} - P_{J}\widetilde{\mathscr{R}}_{\gamma}} + \normtemp{P_{J}\widetilde{\mathscr{R}}_{\gamma} - P_{J}\widetilde{\mathscr{R}}_{\gamma_0}}  + \normtemp{P_{J}\widetilde{\mathscr{R}}_{\gamma_0} - \widetilde{\mathscr{R}}_{\gamma_0}}\\
    &\leq 2\sup_{\gamma'\in\Gamma'}\normtemp{\widetilde{\mathscr{R}}_{\gamma'} - P_{J}\widetilde{\mathscr{R}}_{\gamma'}}  + \normtemp{P_{J}\widetilde{\mathscr{R}}_{\gamma} - P_{J}\widetilde{\mathscr{R}}_{\gamma_0}}\,.
\end{align*}

Next, we control the truncation error represented by the first term in the last line of the preceding display. For any $\varrho \geq 0$, \cref{lem:op_to_hs_rn} (applied with $K=J$, $r=-1/2$, $s=1/2$, and $q=-p=\varrho(d-1) + 1/2$) delivers the bound
\begin{align*}
    \normtemp{{\widetilde{\mathscr{R}}_{\gamma}} - P_{J}\widetilde{\mathscr{R}}_{\gamma}}\leq C \normtemp{\widetilde{\mathscr{R}}_{\gamma}}_{\mathscr{L}(H^{-(\varrho+1)(d-1)- 1/2}_\diamond;H_{\phantom{\diamond}}^{\varrho(d-1) + 1/2}/\mathbb{C})} J^{-\varrho}\leq C_{\varrho,d} J^{-\varrho}\,.
\end{align*}
The final inequality in the last display is due to \cref{lem:ntd_unif_op} (applied with $s=-(\varrho+1)(d-1)-1/2$ and $t=\varrho(d-1) + 1/2$). The constant $C_{\varrho,d}$ depends on $\varrho$ and $d$ but does not depend on $\gamma$. Thus, $C_{\varrho,d} J^{-\varrho}$ also upper bounds the supremum.

Now fix real numbers $s$ and $t$. To control the second term in the error decomposition, we apply \cref{lem:ntd_norm_equiv} with $K=J$, $r=-1/2$, $s=1/2$, $p=s$, and $q=t$. This finite-dimensional norm equivalence result gives
\begin{align*}
    \normtemp{P_J\widetilde{\mathscr{R}}_{\gamma} - P_J\widetilde{\mathscr{R}}_{\gamma_0}}&\leq C J^{\frac{p(s,t)}{d-1}}\normtemp{\widetilde{\mathscr{R}}_{\gamma} -\widetilde{\mathscr{R}}_{\gamma_0}}_{\mathrm{HS}(H^{s}_\diamond;H^{t}/\mathbb{C})}\,,
\end{align*}
where $p(s,t)\coloneqq (s+1/2)_+ + (1/2-t)_+\geq 0$ and $a\mapsto a_+\coloneqq\max(0,a)$. 

Finally, we balance the preceding two upper bounds with a judicious choice of truncation level $J$. For another constant $c_{\varrho,d}>0$, it holds that
\begin{align*}
    x \coloneqq \bigl(c_{\varrho,d} \normtemp{\widetilde{\mathscr{R}}_{\gamma} -\widetilde{\mathscr{R}}_{\gamma_0}}_{\mathrm{HS}(H^{s}_\diamond;H^{t}/\mathbb{C})}\bigr)^{-\frac{d-1}{\varrho(d-1) + p(s,t)}}
\end{align*}
solves the equation $C_{\varrho,d}x^{-\varrho} = C x^{p(s,t)/(d-1)}\normtemp{\widetilde{\mathscr{R}}_{\gamma} -\widetilde{\mathscr{R}}_{\gamma_0}}_{\mathrm{HS}(H^{s}_\diamond;H^{t}/\mathbb{C})}$. It further holds that $x\geq {c_\varrho,d}'$ for a constant $c_{\varrho,d}'>0$. That is, $x$ is bounded away from zero uniformly in $\gamma$ and $\gamma_0$ because $\sup_{(\gamma,\gamma_0)\in\Gamma'\times\Gamma'}\normtemp{\widetilde{\mathscr{R}}_{\gamma} -\widetilde{\mathscr{R}}_{\gamma_0}}_{\mathrm{HS}(H^{s}_\diamond;H^{t}/\mathbb{C})}\leq C$ by the triangle inequality and \cref{lem:op_to_hs_rn,lem:ntd_unif_op}. Since $J$ was arbitrary, choosing the truncation level $J\coloneqq \ceil{x} \in \mathbb{N}$ implies that
\begin{align*}
    \normtemp{\mathscr{R}_{\gamma}-\mathscr{R}_{\gamma_0}}_{\mathscr{L}(H_\diamond^{-1/2};H_{\phantom{\diamond}}^{1/2}/\mathbb{C})}&\leq C \normtemp[\big]{\widetilde{\mathscr{R}}_{\gamma} -\widetilde{\mathscr{R}}_{\gamma_0}}_{\mathrm{HS}(H^{s}_\diamond;H^{t}/\mathbb{C})}^{\frac{\varrho(d-1)}{\varrho(d-1) + p(s,t)}}\\
    &= C \normtemp[\big]{\mathscr{R}_{\gamma} -\mathscr{R}_{\gamma_0}}_{\mathrm{HS}(H^{s}_\diamond;H^{t}/\mathbb{C})}^{\frac{\varrho(d-1)}{\varrho(d-1) + p(s,t)}}\,.
\end{align*}
Setting $\varrho\coloneqq p(s,t)/(d-1)$ if $p(s,t)>0$ and $\varrho>0$ otherwise completes the proof.

\label{def:kernel_integral}
    Let $\tau>0$ and $r_d\coloneqq \frac{d-1}{2}-1+\tau$. For any $\gamma\in\Gamma'$ and NtD map $\mathscr{R}_{\gamma}$, let $\kappa_\gamma\in L^2({\partial\Omega}\times{\partial\Omega};\mathbb{R})$ be the unique, real, integral (Schwartz) kernel of $\mathscr{R}_{\gamma} \mathcal{C}^{r_d/2}\in\mathrm{HS}(L^2_\diamond({\partial\Omega}))$. That is, $\kappa_\gamma\colon{\partial\Omega}\times{\partial\Omega}\to\mathbb{R} $ is such that
    \begin{align}\label{eqn:ntd_action_as_integral}
        \mathscr{R}_{\gamma} \mathcal{C}^{r_d/2} g =\int_{{\partial\Omega}} \kappa_\gamma({\,\cdot\,}, y)g(y)\sigma(dy)
    \end{align}
    for all $g\in L^2_\diamond({\partial\Omega})$.

With the real Hilbert spaces $\mathcal{H}_1$ and $\mathcal{H}_2$ now fixed, we define the nonlinear EIT inversion operator with domain
\begin{align}\label{eqn:domain_of_inverse}
    \mathrm{Dom}(\Psi^\star)\coloneqq \set{\kappa_\gamma}{\gamma\in\mathcal{X}_d(R)} \subseteq L^2({\partial\Omega}\times{\partial\Omega})
\end{align}
by the expression
\begin{align}\label{eqn:inverse_map_final_def}
\begin{split}
    \Psi^\star\colon \mathrm{Dom}(\Psi^\star)&\to L^2(\Omega)\,,\\ 
    \kappa_\gamma&\mapsto\gamma\,,
\end{split}
\end{align}
where $\kappa_\gamma$ is the integral kernel corresponding to a smoothed NtD map from \cref{def:kernel_integral}.

\label{lem:change_of_norm}
    Let $\mathcal{C}$ be as in \eqref{eqn:inverse_shifted_neumann_lap}.
    For any real numbers $s$ and $t$, any $T\in\mathrm{HS}(H^s_\diamond({\partial\Omega});H^t_\diamond({\partial\Omega}))$, and any $r\geq 0$, it holds that
    \begin{align}
        \normtemp[\big]{T}_{\mathrm{HS}(H^s_\diamond({\partial\Omega});H^t_\diamond({\partial\Omega}))} = \normtemp[\big]{T\mathcal{C}^{r/2}}_{\mathrm{HS}(H^{s-r}_\diamond({\partial\Omega});H^t_\diamond({\partial\Omega}))}\,.
    \end{align}

\label{prop:stability_kernel}
    If $d\geq 2$ and $R>0$, then there exists a constant $C^\star>0$ such that for any $\gamma\in\mathcal{X}_d(R)$ and any $\gamma_0\in\mathcal{X}_d(R)$, it holds that
    \begin{align}\label{eqn:stability_kernel_in}
        \normtemp{\Psi^\star(\kappa_\gamma)-\Psi^\star(\kappa_{\gamma_0})}_{L^2(\Omega)}\leq C^\star \omega^\star\bigl(\normtemp{\kappa_{\gamma}-\kappa_{\gamma_0}}_{L^2(\partial\Omega\times{\partial\Omega})}\bigr)\,,
    \end{align}
    where $t\mapsto \omega^\star(t)\coloneqq \omega(\sqrt{t})$ and $\omega$ is as in \eqref{eqn:modulus_log}.

In the following, we let $C>0$ be a constant that is allowed to change from line to line. Let $\gamma$ and $\gamma_0$ belong to $\mathcal{X}_d(R)$. Let $r_d$ be as in \cref{lem:ntd_hs_any_dim}. Since $\Psi^\star(\kappa_\gamma)=\gamma$ by definition \eqref{eqn:inverse_map_final_def} and moduli of continuity are increasing functions, successive application of \cref{thm:stability}, \cref{lem:ntd_to_dtn}, and \cref{lem:hs_to_op} (with $s=r_d$ and $t=0$) yield the inequalities
\begin{align*}
    \normtemp{\Psi^\star(\kappa_\gamma)-\Psi^\star(\kappa_{\gamma_0})}_{L^2(\Omega)}&=\normtemp{\gamma-\gamma_0}_{L^2(\Omega)}\\
    &\leq C\omega\bigl(\normtemp{\Lambda_{\gamma}-\Lambda_{\gamma_0}}_{\mathscr{L}(H^{1/2}({\partial\Omega})/\mathbb{C};H^{-1/2}({\partial\Omega}))}\bigr)\\
    &\leq C\omega\bigl(\normtemp{\mathscr{R}_{\gamma}-\mathscr{R}_{\gamma_0}}_{\mathscr{L}(H^{-1/2}_\diamond({\partial\Omega});H_{\phantom{\diamond}}^{1/2}({\partial\Omega})/\mathbb{C})}\bigr)\\
    &\leq C \omega\mathopen{}\mathclose\bgroup\originalleft(\normtemp{\mathscr{R}_{\gamma}-\mathscr{R}_{\gamma_0}}^{1/2}_{\mathrm{HS}(H^{r_d}_\diamond({\partial\Omega});L^2({\partial\Omega})/\mathbb{C})}\aftergroup\egroup\originalright)\,.
\end{align*}
Next, \cref{lem:change_of_norm}, \cref{lem:ntd_hs_any_dim}, and \cref{def:kernel_integral} imply that
\begin{align*}
    \normtemp[\big]{\mathscr{R}_{\gamma}-\mathscr{R}_{\gamma_0}}_{\mathrm{HS}(H^{r_d}_\diamond({\partial\Omega});L^2({\partial\Omega})/\mathbb{C})}&=\normtemp[\big]{\mathscr{R}_{\gamma}\mathcal{C}^{r_d/2}-\mathscr{R}_{\gamma_0}\mathcal{C}^{r_d/2}}_{\mathrm{HS}(L^2_\diamond({\partial\Omega}))}\\
    &=\normtemp{\kappa_\gamma-\kappa_{\gamma_0}}_{L^2({\partial\Omega}\times{\partial\Omega})}\,.
\end{align*}
To achieve the last equality in the previous display, we used linearity and the fact that the mapping from a $L^2(\partial\Omega\times \partial\Omega)$ kernel function to the $\mathrm{HS}(L^2_\diamond(\partial\Omega)) $ integral operator with that same kernel function is an isometric isomorphism \cite[Prop.~2.8.6, p.~74]{arveson2002short}. Putting together the pieces, we deduce that
\begin{align*}
    \normtemp{\Psi^\star(\kappa_\gamma)-\Psi^\star(\kappa_{\gamma_0})}_{L^2(\Omega)}\leq C\omega\bigl(\normtemp{\kappa_\gamma-\kappa_{\gamma_0}}_{L^2({\partial\Omega}\times{\partial\Omega})}^{1/2}\bigr)
\end{align*}
as asserted.

\label{thm:extension_eit_kernel}
    Let $\Psi^\star\colon\mathrm{Dom}(\Psi^\star)\subseteq L^2({\partial\Omega}\times{\partial\Omega})\to L^2(\Omega)$ be as in \eqref{eqn:domain_of_inverse} and \eqref{eqn:inverse_map_final_def}. Let $C^\star$ and $\omega^\star$ be as in \cref{prop:stability_kernel}. There exists $\widetilde{\Psi}^\star\colon L^2({\partial\Omega}\times{\partial\Omega})\to L^2(\Omega)$ such that $\widetilde{\Psi}^\star(\kappa)=\Psi^\star(\kappa)$ for all $\kappa\in\mathrm{Dom}(\Psi^\star)$, and
    \begin{align}\label{eqn:stability_kernel_out}
        \normtemp{\widetilde{\Psi}^\star(\kappa)-\widetilde{\Psi}^\star(\kappa_0)}_{L^2(\Omega)}\leq C^\star \omega^\star\bigl(\normtemp{\kappa-\kappa_0}_{L^2(\partial\Omega\times{\partial\Omega})}\bigr)
    \end{align}
    for all $\kappa\in L^2({\partial\Omega}\times{\partial\Omega})$ and all $\kappa_0\in L^2({\partial\Omega}\times{\partial\Omega})$.

\label{thm:forward_map_lip}
    There exists $Q>2$ depending only on $d$, $m$, and $M$ such that the following holds. For any $q'\in (2,Q)$, define $q\in(2,\infty)$ by the equation $1/q +1/q' +1/2=1$. Then for any $\gamma$ and $\gamma_0$ belonging to $\Gamma'$, it holds that
    \begin{align}
        \normtemp{\mathscr{R}_{\gamma}-\mathscr{R}_{\gamma_0}}_{\mathscr{L}(H_\diamond^{-1/2}({\partial\Omega});H_{\phantom{\diamond}}^{1/2}({\partial\Omega})/\mathbb{C})}\leq C\normtemp{\gamma-\gamma_0}_{L^q(\Omega)}\,.
    \end{align}
    The constant $C>0$ depends on $d$, $q'$, $m$, $M$, $\Omega$, and $\Omega'$.

\label{lem:op_to_hs}
    For any real numbers $s$ and $t$, there exists $C>0$ depending on $d$, $s$, $t$, $\Omega$, $\Omega'$, $m$, and $M$ such that for all $\gamma$ and $\gamma_0$ belonging to $\Gamma'$, it holds that
    \begin{align}\label{eqn:op_to_hs}
        \normtemp{\mathscr{R}_{\gamma}-\mathscr{R}_{\gamma_0}}_{\mathrm{HS}(H^s_\diamond({\partial\Omega});H^t({\partial\Omega})/\mathbb{C})}
        \leq 
        C\normtemp{\mathscr{R}_{\gamma}-\mathscr{R}_{\gamma_0}}^{1/2}_{\mathscr{L}(H^{-1/2}_\diamond({\partial\Omega});H_{\phantom{\diamond}}^{1/2}({\partial\Omega})/\mathbb{C})}\,.
    \end{align}

\label{cor:forward_stability_kernel}
    There exists $q>2$ depending only on $d$, $m$, and $M$ such that for any $p\in[1,\infty)$ and any $\gamma$ and $\gamma_0$ belonging to $\Gamma'$, it holds that
	\begin{align}\label{eqn:forward_stability_kernel}
		\normtemp[\big]{\kappa_\gamma-\kappa_{\gamma_0}}_{L^2(\partial\Omega\times\partial\Omega)}\leq C\normtemp[\big]{\gamma-\gamma_0}_{L^p(\Omega)}^{\frac12\min\mathopen{}\mathclose\bgroup\originalleft(1, \frac{p}{q}\aftergroup\egroup\originalright)}\,.
	\end{align}
	The constant $C>0$ depends on $d$, $p$, $q$, $m$, $M$, $\Omega$, and $\Omega'$.

Application of \cref{thm:forward_map_lip} and \cref{lem:op_to_hs} delivers a $q>2$ such that
\begin{align*}
    \normtemp{\mathscr{R}_{\gamma}-\mathscr{R}_{\gamma_0}}_{\mathrm{HS}(H^s_\diamond({\partial\Omega});H^t({\partial\Omega})/\mathbb{C})}
        \leq 
        C\normtemp{\gamma-\gamma_0}^{1/2}_{L^q(\Omega)}\,.
\end{align*}
By \cref{lem:change_of_norm} and \cref{lem:ntd_hs_any_dim}, choosing $s=r_d$ and $t=0$ (or $s=r_d=0$ if $d=2)$ in the previous display gives
\begin{align*}
    \normtemp{\mathscr{R}_{\gamma}-\mathscr{R}_{\gamma_0}}_{\mathrm{HS}(H^{r_d}_\diamond;L^2/\mathbb{C})}
    =
    \normtemp{\mathscr{R}_{\gamma} \mathcal{C}^{r_d/2}-\mathscr{R}_{\gamma_0} \mathcal{C}^{r_d/2}}_{\mathrm{HS}(L_\diamond^2)}=\normtemp{\kappa_\gamma-\kappa_{\gamma_0}}_{L^2(\partial\Omega\times\partial\Omega)}\,.
\end{align*}
If $p\geq q$, the asserted result \eqref{eqn:forward_stability_kernel} follows by monotonicity of $L^p$ norms. Otherwise, $p<q$ and we use the topological equivalence of the $L^p(\Omega)$ distances on $\Gamma\supseteq\Gamma'$. 
In this case, for any $\gamma$ and $\gamma_0$ in $\Gamma'$, it holds that
\begin{align*}
    \normtemp{\gamma-\gamma_0}_{L^q(\Omega)}&=\biggl(\int_\Omega\abstemp{\gamma(x)-\gamma_0(x)}^{q-p}\abstemp{\gamma(x)-\gamma_0(x)}^{p}\dd{x}\biggr)^{1/q}\\
    &\leq (2M)^{1-p/q}\normtemp{\gamma-\gamma_0}_{L^p(\Omega)}^{p/q}\,.
\end{align*}
Putting together the pieces completes the proof.

Clearly $\mathcal{X}_d(R)\subseteq L^p(\Omega)$ by definition \eqref{eqn:conductivity_set}. To show that $\mathcal{X}_d(R)$ is closed in $L^p(\Omega)$, let $\{\gamma_n\}_{n\in\mathbb{N}}\subseteq \mathcal{X}_d(R)$ be a sequence such that $\gamma_n\to\gamma\in L^p(\Omega)$ in $L^p(\Omega)$ as $n\to\infty$. First, we show that $\gamma\in\Gamma$. Since $\Omega$ has finite Lebesgue measure, convergence in $L^p(\Omega)$ implies the existence of a subsequence $\{\gamma_{n_k}\}$ such that $\gamma_{n_k}(x)\to\gamma(x)$ as $k\to\infty$ for a.e. $x\in\Omega$. Thus,
\begin{align*}
    \abstemp{\gamma(x)}\leq \abstemp{\gamma_{n_k}(x)} + \abstemp{\gamma(x)-\gamma_{n_k}(x)}
    \leq M + \abstemp{\gamma(x)-\gamma_{n_k}(x)}\,.
\end{align*}
Taking the limit superior shows that $\gamma(x)\leq\abstemp{\gamma(x)}\leq M$ for a.e. $x\in\Omega$. Thus, $\gamma\in L^\infty(\Omega)$. The strictly positive lower bound is similar because
\begin{align*}
    \gamma(x)\geq \gamma_{n_k}(x) - \abstemp{\gamma_{n_k}(x)-\gamma(x)}
    \geq m - \abstemp{\gamma_{n_k}(x)-\gamma(x)}\,.
\end{align*}
Taking the limit inferior, we deduce that $\gamma\in\Gamma$.

Next, we show that $\gamma\in \Gamma'$ is identically one in a neighborhood of the boundary. Let $E=\Omega\setminus\Omega'$, where $\overline{\Omega'}\subset\Omega$. By hypothesis, $\gamma_n=\mathds{1}$ a.e. on $E$. Thus
\begin{align*}
    \int_E\abstemp{1-\gamma(x)}^p\dd{x}=\int_E\abstemp{\gamma_n(x)-\gamma(x)}^p\dd{x}\leq\int_\Omega\abstemp{\gamma_n(x)-\gamma(x)}^p\dd{x}
\end{align*}
for any $n$. By taking the limit superior, it follows that $\int_E\abstemp{1-\gamma(x)}^p\dd{x}=0$. This implies that $\gamma=\mathds{1}$ a.e. on $E$ as required. Hence, $\gamma\in\Gamma'$.

To conclude that $\gamma\in\mathcal{X}_d(R)$, we must prove that the $L^p$-limit $\gamma$ satisfies the \emph{a priori} bounds in the definition~\eqref{eqn:conductivity_set} of $\mathcal{X}_d(R)$. Beginning with dimension $d=2$, we must establish the BV norm bound. Since $\sup_{n\in\mathbb{N}}\normtemp{\gamma_n}_{\mathsf{BV}}\leq R$, it holds that
\begin{align*}
    \normtemp{\gamma}_{L^1(\Omega)}=\int_\Omega\lim_{k\to\infty}\abstemp{\gamma_{n_k}(x)}\dd{x}
    \leq \liminf_{k\to\infty}\int_\Omega\abstemp{\gamma_{n_k}(x)}\dd{x}
    = \liminf_{k\to\infty}\normtemp{\gamma_{n_k}}_{L^1(\Omega)}\leq R
\end{align*}
by Fatou's lemma. Next, the total variation functional $V({\,\cdot\,};\Omega)\colon L^1_{\mathrm{loc}}(\Omega)\to\mathbb{R}_{\geq 0}\cup\{\infty\}$ is lower semi-continuous in $L^1_{\mathrm{loc}}(\Omega)$ \cite[Exercise~14.3~(iii), p.~460]{leoni2017first}. Since $p\geq 1$, the sequence $\{\gamma_n\}_{n\in\mathbb{N}}$ and limit $\gamma$ both belong to $L^1_{\mathrm{loc}}(\Omega)$. It follows that $V(\gamma;\Omega)\leq \liminf_{n\to\infty} V(\gamma_n;\Omega)\leq R$. Therefore, $\normtemp{\gamma}_{\mathsf{BV}}\leq R$ as desired.

Now consider $d\geq 3$. We have $\sup_{n\in\mathbb{N}}\normtemp{\gamma_n}_{C^{1,\alpha}}\leq R$. Let $\beta<\alpha$. By the compactness of the embedding $C^{1,\alpha}(\overline{\Omega})\hookrightarrow C^{1,\beta}(\overline{\Omega})$ \cite[Thm.~1.34, pp.~11--12]{adams2003sobolev}, there exists a subsequence $\{\gamma_{n_k}\}_{k\in\mathbb{N}}$ and a limit $\gamma'\in C^{1,\beta}(\overline{\Omega})$ such that $\lim_{k\to\infty}\normtemp{\gamma_{n_k}-\gamma'}_{C^{1,\beta}}=0$. Thus, it also holds that
\begin{align*}
    \normtemp{\gamma_{n_k}-\gamma'}_{L^p}\lesssim \normtemp{\gamma_{n_k}-\gamma'}_{L^\infty}=\sup_{x\in\Omega}\abstemp{\gamma_{n_k}(x)-\gamma'(x)}\leq \normtemp{\gamma_{n_k}-\gamma'}_{C^{1,\beta}}\to 0
\end{align*}
as $k\to\infty$. By uniqueness of limits, we deduce that $\gamma=\gamma'$ a.e. on $\Omega$ and $\gamma=\gamma'$ in $L^p$. Identifying $\gamma$ with its continuous representative $\gamma'$, in particular it holds that $\gamma_{n_k}\to\gamma$ as $k\to\infty$ in $C^1(\overline{\Omega})$. Thus
\begin{align*}
    \normtemp{\gamma}_{C^1}\leq \limsup_{k\to\infty}\normtemp{\gamma_{n_k}}_{C^1} + \limsup_{k\to\infty}\normtemp{\gamma - \gamma_{n_k}}_{C^1}\leq R\,.
\end{align*}
Finally, let $\nu$ be a multi-index with $\abstemp{\nu}=1$ and let $(x,x')\in\Omega\times\Omega$. Then
\begin{align*}
    \abstemp[\big]{(\partial^\nu\gamma)(x)-(\partial^\nu\gamma)(x')}=\limsup_{k\to\infty}\abstemp[\big]{(\partial^\nu\gamma_{n_k})(x)-(\partial^\nu\gamma_{n_k})(x')}\leq R\, \abstemp{x-x'}^\alpha
\end{align*}
because $\{\gamma_{n_k}\}_{k\in\mathbb{N}}\subseteq \mathcal{X}_d(R)$. Since $\nu$, $x$, and $x'$ are arbitrary, the assertion $\normtemp{\gamma}_{C^{1,\alpha}}\leq R $ follows. This completes the proof.

Since $\mathcal{X}_d(R)$ is closed in the $L^p(\Omega)$ topology by \cref{lem:closed_set}, compactness will follow by establishing relative compactness (i.e., precompactness) in $L^p(\Omega)$. 

First let $d=2$. In this case, our argument is similar to that in \cite[Appendix C]{bhattacharya2023learning}. The proof uses the Frech\'et--Kolmogorov--Riesz (FKR) compactness theorem \cite[Thm.~4.26, Sec.~4.5, p.~111]{brezis2011functional}. This theorem requires $L^p(\mathbb{R}^d)$ boundedness and $L^p(\mathbb{R}^d)$ equicontinuity estimates on the whole of $\mathbb{R}^d$. To this end, define the set $\widetilde{\mathcal{X}}\coloneqq \set{\widetilde{\gamma}-\mathds{1} \colon\mathbb{R}^2\to\mathbb{R}}{\gamma\in\mathcal{X}_2(R)}$, where $\widetilde{\gamma}\colon\mathbb{R}^2\to\mathbb{R}$ is the continuous extension of $\gamma$ by one outside of $\Omega$. For the boundedness over $\widetilde{\mathcal{X}}$, notice that
\begin{align*}
    \normtemp{\widetilde{\gamma}-\mathds{1}}_{L^p(\mathbb{R}^d)}=\normtemp{\gamma-\mathds{1}}_{L^p(\Omega)}\leq  (M+1)\abstemp{\Omega}^{1/p}
\end{align*}
because $\widetilde{\gamma}-\mathds{1}\equiv 0$ outside of $\Omega$. For equicontinuity on average, we first recall \eqref{eqn:modulus_sup} and the translation-by-$y$ operator $\tau_y$ defined by $(\tau_y f)(x)= f(x+y)$ for fixed $y\in\mathbb{R}^d\setminus\{0\}$ and for any $x\in\mathbb{R}^d$. For any $h\in\mathbb{R}^d$, we compute that
\begin{align*}
    \normtemp{\tau_h(\widetilde{\gamma}-\mathds{1}) - (\widetilde{\gamma}-\mathds{1})}_{L^\infty(\mathbb{R}^d)}=\normtemp{\tau_h\widetilde{\gamma}-\widetilde{\gamma}}_{L^\infty(\mathbb{R}^d)}
    \leq 2\normtemp{\widetilde{\gamma}}_{L^\infty(\mathbb{R}^d)}
    \leq 2 M\,.
\end{align*}
Also, by an argument similar to the one used in the proof of \cref{thm:stability},
\begin{align*}
    \normtemp{\tau_h(\widetilde{\gamma}-\mathds{1}) - (\widetilde{\gamma}-\mathds{1})}_{L^1(\mathbb{R}^d)}=\normtemp{\tau_h\widetilde{\gamma}-\widetilde{\gamma}}_{L^1(\mathbb{R}^d)}
    \leq V(\widetilde{\gamma};\mathbb{R}^d)\abstemp{h}
    = V(\gamma;\Omega)\abstemp{h}\leq R\abstemp{h}\,.
\end{align*}
We again invoked \cref{lem:tv_identity}. By interpolating the $L^1$ and $L^\infty$ norms, it follows that
\begin{align*}
    \normtemp{\tau_h(\widetilde{\gamma}-\mathds{1}) - (\widetilde{\gamma}-\mathds{1})}_{L^p(\mathbb{R}^d)}&\leq \normtemp{\tau_h\widetilde{\gamma} - \widetilde{\gamma}}_{L^\infty(\mathbb{R}^d)}^{1-1/p}\normtemp{\tau_h\widetilde{\gamma} - \widetilde{\gamma}}_{L^1(\mathbb{R}^d)}^{1/p}\\
    &\leq (2 M)^{1-1/p}R^{1/p}\abstemp{h}^{1/p}\,,
\end{align*}
which tends to zero uniformly over $\widetilde{\mathcal{X}}$ as $\abstemp{h}\to0$. Then, the FKR compactness theorem asserts that $\widetilde{\mathcal{X}}|_{\Omega}\coloneqq \set{\gamma-\mathds{1}\colon \Omega\to \mathbb{R}}{\gamma\in\mathcal{X}_2(R)}$ is relatively compact in $L^p(\Omega)$. From this fact, it is easy to see that $\mathcal{X}_2(R)$ itself is relatively compact in $L^p(\Omega)$.

Now let $d\geq 3$. Let $\{\gamma_n\}\subseteq\mathcal{X}_d(R)$ be a sequence. Since $\sup_{n\in\mathbb{N}}\normtemp{\gamma_n}_{C^{1,\alpha}}\leq R$, the compactness of the embedding $C^{1,\alpha}(\overline{\Omega})\hookrightarrow C^{1,\beta}(\overline{\Omega})$ for $\beta<\alpha$ \cite[Thm.~1.34, pp.~11--12]{adams2003sobolev} delivers the existence of a subsequence $\{\gamma_{n_k}\}_{k\in\mathbb{N}}$ and a limit $\gamma'\in C^{1,\beta}(\overline{\Omega})$ such that
\begin{align*}
    \normtemp{\gamma_{n_k}-\gamma'}_{L^p}\lesssim \normtemp{\gamma_{n_k}-\gamma'}_{L^\infty}=\sup_{x\in\Omega}\abstemp{\gamma_{n_k}(x)-\gamma'(x)}\leq \normtemp{\gamma_{n_k}-\gamma'}_{C^{1,\beta}}\to 0
\end{align*}
as $k\to\infty$. This proves that $\mathcal{X}_d(R)$ is relatively compact in $L^p(\Omega)$ for $d\geq 3$.

For every $j$ and $k$, define the diffeomorphism
\begin{align}\label{eqn:coord_backward}
    \begin{split}
        \Phi_{jk}^{-1}\colon W_j\times W_k&\to U_j\times U_k\\
        (x,y)&\mapsto \bigl(\phi_j^{-1}(x),\phi_k^{-1}(y)\bigr)
    \end{split}
\end{align}
and its associated pullback linear operator
\begin{align}\label{eqn:coord_backward_pull}
\begin{split}
    (\Phi_{jk}^{-1})^*\colon L^2({\partial\Omega}\times{\partial\Omega}) &\to L^2(W_j\times W_k)\\
    h&\mapsto h\circ \Phi_{jk}^{-1}\,.
\end{split}
\end{align}

For any $h$, we also define the zero-extended continuous pullback operator $(\widetilde{\Phi}_{jk}^{-1})^*\colon L^2({\partial\Omega}\times{\partial\Omega}) \to L^2(\mathfrak{D}\times \mathfrak{D})$ by
\begin{align}\label{eqn:pull_inv_zero}
    (x,y)\mapsto \bigl((\widetilde{\Phi}_{jk}^{-1})^* h\bigr)(x,y)\coloneqq
    \begin{cases}
        \bigl(({\Phi}_{jk}^{-1})^* h\bigr)(x,y)\, , & \text{if }\, (x,y)\in W_j\times W_k\,,\\
        0\, , & \text{otherwise}\,.
    \end{cases}
\end{align}

Finally, we define the linear local-to-global map
\begin{align}\label{eqn:local_to_global}
    \begin{split}
        {\mathsf{L}}\colon L^2(\mathfrak{D}\times \mathfrak{D})^{J\times J}&\to L^2({\partial\Omega}\times{\partial\Omega})\\
        \bigl\{f_{jk}\}_{j,k=1}^J&\mapsto  \sum_{j,k=1}^J \mathsf{M}_{jk}\widetilde{\Phi}_{jk}^* f_{jk}\,.
    \end{split}
\end{align}

Let $h\in L^2({\partial\Omega}\times{\partial\Omega})$ and $(x,y)\in{\partial\Omega}\times{\partial\Omega}$. By definition,
\begin{align*}
    ({\mathsf{L}}{\mathsf{G}}h)(x,y)&=\sum_{j,k=1}^J \bigl(\mathsf{M}_{jk}\widetilde{\Phi}_{jk}^*(\widetilde{\Phi}_{jk}^{-1})^* h\bigr)(x,y)\\
    &=\sum_{j,k=1}^J \psi_j(x)\psi_k(y)\bigl(\widetilde{\Phi}_{jk}^*(\widetilde{\Phi}_{jk}^{-1})^* h\bigr)(x,y)\\
    &=\sum_{(j,k)\in\set{(m,n)}{(x,y)\in U_m\times U_n}}
    \psi_j(x)\psi_k(y)\bigl((\widetilde{\Phi}_{jk}^{-1})^* h\bigr)\bigl(\phi_j(x),\phi_k(y)\bigr)\,.
\end{align*}
Also, \eqref{eqn:pull_inv_zero} implies that
\begin{align*}
    \bigl((\widetilde{\Phi}_{jk}^{-1})^* h\bigr)\bigl(\phi_j(x),\phi_k(y)\bigr)&=\bigl(({\Phi}_{jk}^{-1})^* h\bigr)\bigl(\phi_j(x),\phi_k(y)\bigr)\\
    &=h(x,y)\,.
\end{align*}
We deduce that
\begin{align*}
    ({\mathsf{L}}{\mathsf{G}}h)(x,y)=\sum_{(j,k)\in\set{(m,n)}{(x,y)\in U_m\times U_n}}
    \psi_j(x)\psi_k(y) h(x,y)=h(x,y)
\end{align*}
because $\{\mathsf{M}_{jk}\mathds{1}\}_{j,k=1}^J$ is a partition of unity subordinate to $\{U_j\times U_k\}_{j,k=1}^J$ with $\mathsf{M}_{jk}\mathds{1}\in C_c^\infty(U_j\times U_k)$. Since $h$, $x$, and $y$ are arbitrary, the assertion is proved.

define $(\mathcal{F} h)(x_1,\ldots, x_d)$ to be equal to
\begin{align}\label{eqn:functional_layer}
    \int_{\mathbb{T}^{d_\mathrm{m}-d}} \kappa(x_{d+1},\ldots, x_{d_\mathrm{m}})h(x_1,\ldots, x_d, x_{d+1},\ldots, x_{d_\mathrm{m}})\dd{x_{d+1}}\cdots \dd{x_{d_\mathrm{m}}}\,.

\label{assump:main}
    Instate the setting of \cref{sec:approx_manifold}. The following hold true:
    \begin{enumerate}[label=(A-\Roman*),leftmargin=2.5\parindent,topsep=1.67ex,itemsep=0.5ex,partopsep=1ex,parsep=1ex]
        \item \sfit{(physical domain)}\label{item:ass_domain} Let $\Omega\subset\mathbb{R}^d$ be a bounded domain with $C^\infty$-smooth boundary such that $\overline{\Omega}\subset (0,1)^d$ and \cref{ass:bilipschitz} holds.

        \item \sfit{(activation function)}\label{item:ass_act} Let $\varsigma \in C^\infty(\mathbb{R})$ be a fixed globally Lipschitz and non-polynomial activation function. For all $\ell\in\mathbb{N}$, it holds that $\varsigma_\ell=\varsigma$ in \eqref{eqn:no_layers}.
    \end{enumerate}

\label{thm:fno_approx_main}
    Suppose that \cref{assump:main} holds. Let $C^\star$ and $\omega^\star$ be as in \cref{prop:stability_kernel}. Let $d\geq 2$ and $R>0$. For any compact set  $K \subset L^2({\partial\Omega}\times{\partial\Omega})$ and any $\delta>0$, the following holds. Let $K_\delta\coloneqq{\{\eta\in K\colon \normtemp{\eta}_{L^2({\partial\Omega}\times{\partial\Omega})}\leq \delta\}}$. For any $\varepsilon>0$, there exists a generalized FNO $\Psi \colon L^2({\partial\Omega}\times{\partial\Omega})\to L^2(\Omega)$ of the form \eqref{eqn:fno_eit} such that
    \begin{align}\label{eqn:fno_approx_main}
        \sup_{(\gamma,\eta)\in \mathcal{X}_d(R)\times K_\delta} \normtemp{\gamma - \Psi(\kappa_\gamma + \eta)}_{L^2(\Omega)} \leq  \varepsilon + C^\star\omega^\star(\delta)\,.
    \end{align}

Let $\widetilde{\Psi}^\star$ be the extension of $\Psi^\star$ from \cref{thm:extension_eit_kernel}. Define the set sum
\begin{align*}
    Z_\delta\coloneqq \set{\kappa_0+\eta_0}{\kappa_0\in \mathrm{Dom}(\Psi^\star)\,\text{ and }\, \eta_0\in K_\delta}\subseteq L^2({\partial\Omega}\times{\partial\Omega})\,.
\end{align*}
The set $\mathrm{Dom}(\Psi^\star)$ from \eqref{eqn:domain_of_inverse} is compact in $L^2({\partial\Omega}\times{\partial\Omega})$ by \cref{cor:compact_set_kernel}. Also, $K_\delta$ is compact because it is a closed subset of the compact set $K\subset L^2({\partial\Omega}\times{\partial\Omega})$. It follows that the sum $Z_\delta$ is also compact in $L^2({\partial\Omega}\times{\partial\Omega})$ because it is the continuous image of the compact set $\mathrm{Dom}(\Psi^\star)\times K_\delta$. Now fix $\varepsilon>0$. We claim that there exists a generalized FNO $\Psi$ of the form \eqref{eqn:fno_eit} such that
\begin{align}\label{eqn:fno_approx_claim}
    \sup_{\kappa\in Z_\delta}\,\normtemp{\widetilde{\Psi}^\star(\kappa)-\Psi(\kappa)}_{L^2(\Omega)}\leq\varepsilon\,.
\end{align}
Under this claim, let $\gamma\in\mathcal{X}_d(R)$ and $\eta\in K_\delta$ be arbitrary. By the definition of $\Psi^\star$ and its extension,
\begin{align*}
    \normtemp{\gamma - \Psi(\kappa_\gamma + \eta)}_{L^2(\Omega)}=\normtemp{\Psi^\star(\kappa_\gamma) - \Psi(\kappa_\gamma + \eta)}_{L^2(\Omega)}=\normtemp{\widetilde{\Psi}^\star(\kappa_\gamma) - \Psi(\kappa_\gamma + \eta)}_{L^2(\Omega)}\,.
\end{align*}
By the triangle inequality, the uniform continuity estimate \eqref{eqn:stability_kernel_out}, and the claim~\eqref{eqn:fno_approx_claim},
\begin{align*}
    \normtemp{\widetilde{\Psi}^\star(\kappa_\gamma) - \Psi(\kappa_\gamma + \eta)}_{L^2(\Omega)}
    &\leq \normtemp{\widetilde{\Psi}^\star(\kappa_\gamma) - \widetilde{\Psi}^\star(\kappa_\gamma+\eta)}_{L^2(\Omega)}\\
    &\qquad\qquad\qquad +\normtemp{\widetilde{\Psi}^\star(\kappa_\gamma+\eta) - \Psi(\kappa_\gamma + \eta)}_{L^2(\Omega)}\\
    &\leq C^\star \omega^\star\bigl(\normtemp{\eta}_{L^2({\partial\Omega}\times{\partial\Omega})}\bigr) + 
    \sup_{\kappa\in Z_\delta}\,\normtemp{\widetilde{\Psi}^\star(\kappa) - \Psi(\kappa)}_{L^2(\Omega)}\\
    &\leq C^\star\omega^\star(\delta) + \varepsilon\,.
\end{align*}
This implies the assertion \eqref{eqn:fno_approx_main}. It remains to prove the claim \eqref{eqn:fno_approx_claim}.

Recall the global-to-local map $\mathsf{G}$ from \eqref{eqn:global_to_local} and the local-to-global map $\mathsf{L}$ from \eqref{eqn:local_to_global}. Write
\begin{align*}
    \Psi\coloneqq \Psi_0\circ\mathsf{G}\quad \text{for some}\quad\Psi_0\colon L^2(\mathfrak{D}\times \mathfrak{D};\mathbb{R}^{J^2})\to L^2(\Omega)
\end{align*}
to be determined.
By \cref{lem:left_inv_pou},
\begin{align}\label{eqn:fno_approx_claim_h}
    \begin{split}
        \sup_{\kappa\in Z_\delta}\,\normtemp{\widetilde{\Psi}^\star(\kappa) - \Psi(\kappa)}_{L^2(\Omega)}&=\sup_{\kappa\in Z_\delta}\,\normtemp{(\widetilde{\Psi}^\star\circ \mathsf{L})(\mathsf{G} \kappa)-\Psi_0(\mathsf{G} \kappa)}_{L^2(\Omega)}\\
        &= \sup_{h\in \mathsf{G}(Z_\delta)}\normtemp{(\widetilde{\Psi}^\star\circ \mathsf{L})(h)-\Psi_0(h)}_{L^2(\Omega)}\,.
    \end{split}
\end{align}
Since $Z_\delta$ is compact in $L^2({\partial\Omega}\times{\partial\Omega})$, the set $\mathsf{G}(Z_\delta)$ is compact in $L^2(\mathfrak{D}\times \mathfrak{D};\mathbb{R}^{J^2})$ by the continuity of $\mathsf{G}$. To find $\Psi_0$ that uniformly approximates $\widetilde{\Psi}^\star\circ \mathsf{L}$ over $\mathsf{G}(Z_\delta)$, we adapt ideas from the proof of \cite[Thm.~3.2, pp.~34--35]{huang2025operator}. First, we associate to $\widetilde{\Psi}^\star\circ \mathsf{L}$ another operator $\Upsilon^\star$ that is more compatible with existing FNO approximation theorems requiring matching domain dimensions \cite[Sec.~2]{kovachki2021universal}. Second, we relate $\Upsilon^\star$ back to $\widetilde{\Psi}^\star\circ \mathsf{L}$ by introducing a linear functional averaging layer. This allows us to bound the display \eqref{eqn:fno_approx_claim_h}. Last, we demonstrate that our approach indeed leads to an approximation of the form \eqref{eqn:fno_eit}.

\subparagraph*{\emph{\textbf{Step 1.}}}
Since $\overline{\Omega}\subset(0,1)^d$ and $\mathbb{T}^d\simeq[0,1]^d_{\mathrm{per}}$, the linear restriction operator 
\begin{align*}
\mathsf{R} \colon L^2(\mathbb{T}^d)\to L^2(\Omega)
\end{align*}
given by $u\mapsto u|_{\Omega}$ is well-defined and continuous with norm at most one. Let 
\begin{align*}
    \mathsf{E}\colon L^2(\Omega)\to L^2(\mathbb{T}^d)
\end{align*}
be the continuous linear extension operator from \cite[Lemma~B.1, p.~34, applied with $d_u=d_y=1$ and $s=s'=0$]{huang2025operator}. It holds that $\mathsf{R}\mathsf{E}=\mathrm{Id}_{L^2(\Omega)}$.
Define 
\begin{align*}
    \Upsilon_0^\star\coloneqq \mathsf{E}\circ\widetilde{\Psi}^\star\circ \mathsf{L}\colon L^2(\mathfrak{D}\times\mathfrak{D};\mathbb{R}^{J^2})\to L^2(\mathbb{T}^d)
\end{align*}
so that $\widetilde{\Psi}^\star\circ \mathsf{L}= \mathsf{R}\circ \Upsilon_0^\star$. 
Recall that $d\geq 2$.
Define $\Upsilon^\star\colon L^2(\mathfrak{D}\times\mathfrak{D};\mathbb{R}^{J^2})\to L^2(\mathbb{T}^{2d-2})$ by
\begin{align*}
    \bigl(\Upsilon^\star (h)\bigr)(x_1,x_2,\ldots, x_{2d-3}, x_{2d-2})\coloneqq \bigl(\Upsilon^\star_0 (h)\bigr)(x_1,x_2,\ldots, x_{d-1},x_d)
\end{align*}
for every $h$ and $x=(x_1,\ldots,x_{2d-2})$. The periodic function  $\Upsilon^\star (h)$ is constant in the last $d-2$ dimensions.
Since $\widetilde{\Psi}^\star\colon L^2({\partial\Omega}\times{\partial\Omega})\to L^2(\Omega)$ is continuous by \eqref{eqn:stability_kernel_out}, and so are the linear maps $\mathsf{E}$ and $\mathsf{L}$, the operator $\Upsilon_0^\star$ is also continuous. Moreover,
\begin{align*}
    \normtemp{\Upsilon^\star(h)-\Upsilon^\star(h')}^2_{L^2(\mathbb{T}^{2d-2})}=\normtemp{\Upsilon^\star_0(h)-\Upsilon^\star_0(h')}^2_{L^2(\mathbb{T}^{d})}
\end{align*}
for all $h$ and $h'$. We deduce that $\Upsilon^\star$ is continuous.
Using \cref{assump:main} and the fact that (abusing notation) $\overline{\mathfrak{D}\times\mathfrak{D}}\subset (0,1)^{2d-2}$, the universal approximation theorem for FNOs with periodic outputs \cite[Lemma~B.1, p.~34, applied with $s=s'=0$, $d_u=J^2$, and $d_y=1$]{huang2025operator} shows that there exist a continuous linear extension operator 
\begin{align*}
\mathsf{E}'\colon L^2(\mathfrak{D}\times\mathfrak{D};\mathbb{R}^{J^2})\to L^2(\mathbb{T}^{2d-2};\mathbb{R}^{J^2})    
\end{align*}
and, for every $\varepsilon>0$, an FNO
\begin{align*}
\Psi'\colon L^2(\mathbb{T}^{2d-2};\mathbb{R}^{J^2})\to L^2(\mathbb{T}^{2d-2})    
\end{align*}
of the form \eqref{eqn:fno_torus} such that
\begin{align*}
    \sup_{h\in\mathsf{G}(Z_\delta)}\normtemp{\Upsilon^\star(h)-\Psi'(\mathsf{E}' h)}_{L^2(\mathbb{T}^{2d-2})}\leq \varepsilon\,.
\end{align*}

\subparagraph*{\emph{\textbf{Step 2.}}}
To relate the preceding periodic approximation result back to the claim \eqref{eqn:fno_approx_claim} and the display \eqref{eqn:fno_approx_claim_h}, define the linear operator $\mathsf{A}\colon L^2(\mathbb{T}^{2d-2})\to L^2(\mathbb{T}^d)$ by
\begin{align*}
    u\mapsto \mathsf{A} u\coloneqq \int_{\mathbb{T}^{d-2}}u({\,\cdot\,}, x_{d+1},\ldots, x_{2d-2})\dd{x_{d+1}}\cdots \dd{x_{2d-2}}\,.
\end{align*}
This operator averages the last $d-2$ dimensions of the input function. Since $[0,1]^n$ has Lebesgue measure one for all $n$, Jensen's inequality shows that the map $\mathsf{A}$ has operator norm one (with supremum achieved at the constant function $\mathds{1}$). 
Observe that 
\begin{align*}
    \Upsilon_0^\star=\mathsf{A}\circ \Upsilon^\star\,.
\end{align*}
By defining $\Psi_0\coloneqq \mathsf{R}\circ\mathsf{A}\circ\Psi'\circ\mathsf{E}'$, it holds that
\begin{align*}
\sup_{h\in \mathsf{G}(Z_\delta)}\normtemp{(\widetilde{\Psi}^\star\circ \mathsf{L})(h)-\Psi_0(h)}_{L^2(\Omega)}&=\sup_{h\in \mathsf{G}(Z_\delta)}\normtemp{(\mathsf{R}\circ\mathsf{A}\circ\Upsilon^\star)(h)-\Psi_0(h)}_{L^2(\Omega)}\\
    &\leq \sup_{h\in \mathsf{G}(Z_\delta)}\normtemp{(\mathsf{A}\circ\Upsilon^\star)(h)-(\mathsf{A}\circ\Psi'\circ\mathsf{E}')(h)}_{L^2(\mathbb{T}^d)}\\
    &\leq \sup_{h\in \mathsf{G}(Z_\delta)}\normtemp{\Upsilon^\star(h)-(\Psi'\circ\mathsf{E}')(h)}_{L^2(\mathbb{T}^{2d-2})}\\
    &\leq \varepsilon
\end{align*}
because both $\mathsf{R}$ and $\mathsf{A}$ have operator norm at most one. This delivers the display \eqref{eqn:fno_approx_claim}.

\subparagraph*{\emph{\textbf{Step 3.}}}
To complete the proof of the claim, we must show that our final approximation
\begin{align*}
    \Psi\coloneqq \mathsf{R}\circ\mathsf{A}\circ\Psi'\circ\mathsf{E}'\circ\mathsf{G}
\end{align*}
is of the form \eqref{eqn:fno_eit} with $\mathcal{M}={\partial\Omega}\times{\partial\Omega}$, $d_\mathrm{a}=2d$, $d_\mathrm{m}=2d-2$, and $d_\mathrm{in}=d_\mathrm{out}=1$. By definition of $\Psi'$, \cite[Lemma~B.1, p.~34]{huang2025operator} asserts that there exist a number of layers $T$, channel dimension $d_\mathrm{c}$, matrix $S'\in\mathbb{R}^{d_\mathrm{c}\times J^2}$ determining operator $\mathcal{S}'$ according to \eqref{eqn:pw_lift}, and matrix $Q'\in \mathbb{R}^{1\times d_\mathrm{c}}$ determining operator $\mathcal{Q}'$ according to \eqref{eqn:pw_proj} such that
\begin{align*}
    \Psi'=\mathcal{Q}'\circ \mathcal{L}_L\circ \cdots \circ \mathcal{L}_1\circ \mathcal{S}'\,,
\end{align*}
where the nonlinear operators $\{\mathcal{L}_\ell\}_{\ell=1}^L$ map $L^2(\mathbb{T}^{2d-2};\mathbb{R}^{d_\mathrm{c}})$ into itself and are given in~\eqref{eqn:no_layers} and \eqref{eqn:fno_layer}. The preceding two displays show that we can write
\begin{align*}
    \Psi= \mathcal{Q} \circ\mathcal{R}\circ \mathcal{F}\circ\mathcal{L}_L\circ\cdots\circ\mathcal{L}_1\circ\mathcal{E}\circ \mathcal{S}
\end{align*}
in the form \eqref{eqn:fno_eit} by taking
\begin{align*}
    S&\coloneqq 
    \begin{bmatrix}
        \,0\,&\,\cdots\,& \,0\,& \,1\,
    \end{bmatrix}
    \in\mathbb{R}^{1\times (2d+1)}\quad\text{so that}\quad \mathcal{S}=\mathrm{Id}_{L^2({\partial\Omega}\times{\partial\Omega})}\,,\\
    \mathcal{E} &\coloneqq \mathcal{S}'\circ\mathsf{E}'\circ\mathsf{G}\in\mathscr{L}\bigl(L^2({\partial\Omega}\times{\partial\Omega});L^2(\mathbb{T}^{2d-2};\mathbb{R}^{d_\mathrm{c}})\bigr)\,,\\
    \mathcal{F}&\coloneqq\mathsf{A}\circ \mathcal{Q}'\in \mathscr{L}\bigl(L^2(\mathbb{T}^{2d-2};\mathbb{R}^{d_\mathrm{c}}); L^2(\mathbb{T}^d)\bigr)\,,\\
    \mathcal{R}&\coloneqq\mathsf{R}\in \mathscr{L}\bigl(L^2(\mathbb{T}^d); L^2(\Omega)\bigr)\,,\quad\text{and}\quad\\
    Q&\coloneqq 1\in\mathbb{R}^{1\times 1} \quad\text{so that}\quad \mathcal{Q}=\mathrm{Id}_{L^2(\Omega)}\,.
\end{align*}
The requirement that $\mathcal{E}$ be continuous holds because the global-to-local map $\mathsf{G}\in\mathscr{L}(L^2({\partial\Omega}\times{\partial\Omega}); L^2(\mathfrak{D}\times\mathfrak{D};\mathbb{R}^{J^2}))$, $\mathsf{E}'$, and $\mathcal{S}'$ are all continuous linear operators. Moreover, $\mathcal{F}$ is the composition of two continuous linear maps so it is itself continuous and linear. It may be identified,  via~\eqref{eqn:functional_layer}, with the constant kernel function $\kappa\colon \mathbb{T}^{d-2}\to\mathbb{R}^{1\times d_\mathrm{c}}$ given by $x\mapsto \kappa(x)=Q'$. Being constant, the function $\kappa$ is periodic and has a well-defined Fourier series.
All together, these facts deliver the claimed form of the neural operator approximation.

