\label{lem:lax_milgram_general}
    For any $s\in\mathbb{R}$ and any $g\in {H}_\diamond^s(\partial\Omega)$, there exists $C_s>0$ such that
    \begin{align}\label{eqn:uniform_w_continuity_bound}
        \sup_{\gamma\in\Gamma'}\normtemp{u_{\gamma,g}-u_{\mathds{1},g}}_{H^1(\Omega)/\mathbb{C}}\leq C_s\normtemp{g}_{{H}_\diamond^s(\partial\Omega)}\,,
    \end{align}
    where $u=u_{\gamma',g}$ solves \eqref{eqn:elliptic} with conductivity $\gamma=\gamma'\in\Gamma'$ and Neumann data $g$.

Let $s\in\mathbb{R}$ and $g\in {H}_\diamond^s(\partial\Omega)$ be arbitrary. Let $u_{\mathds{1},g}$ solve the Neumann Laplace equation with Neumann data $g$, i.e., \eqref{eqn:elliptic} with conductivity $\gamma\equiv 1$. This solution exists in $H^{s+3/2}(\Omega)/\mathbb{C}$ and is unique by classical results \cite[Chp.~2, Remark 7.2, pp.~188--189, taking $\Omega=\Omega$, $A=-\Delta$, $f\equiv 0$, $s=s+3/2$, $m=m_0=1$, $g_0=g$, and $N=\{z\mathds{1}\colon z\in\mathbb{C}\}$]{lions2012non}.    
Also fix $\gamma\in\Gamma'$. Consider the PDE
\begin{equation}\label{eqn:elliptic_temp}
    -\nabla\cdot(\gamma \nabla w)=\nabla\cdot(\gamma\nabla u_{\mathds{1},g}) \ \text{ in } \Omega \quad\text{and}\quad \dfrac{\partial w}{\partial \mathsf{n}}=0 \ \text{ on } {\partial\Omega}\, .
\end{equation}
Define sesquilinear form $B_\gamma$ and conjugate linear functional $f_{\gamma,g}$, respectively, by
\begin{align*}
    B_\gamma(w,v)\coloneqq \int_\Omega \gamma\nabla w\cdot\overline{\nabla v}\dd{x} \quad\text{and}\quad f_{\gamma,g}(v)\coloneqq -\int_\Omega \gamma\nabla u_{\mathds{1},g}\cdot \overline{\nabla v}\dd{x}\,.
\end{align*}
The weak form of the Neumann problem \eqref{eqn:elliptic_temp} is to find $w=w_{\gamma,g}\in H^1(\Omega)/\mathbb{C}$ such that
\begin{align}\label{eqn:weak_neumann_temp}
    B_\gamma(w,v)=f_{\gamma,g}(v)\quad\text{for all}\quad v\in H^1(\Omega)/\mathbb{C}\,.
\end{align}
Since such a weak solution $w_{\gamma,g}$ defines a weak solution $u_{\gamma,g}\coloneqq w_{\gamma,g} + u_{\mathds{1},g}$ to the original problem \eqref{eqn:elliptic} \cite[Thm.~A.2 and its proof, pp.~392--394]{hanke2011convex}, it remains to bound the $H^1(\Omega)/\mathbb{C}$ norm of $w_{\gamma,g}$ uniformly over the set $\Gamma'$ of conductivities.

To this end, we apply the Lax--Milgram theorem. To show continuity of $B_\gamma$, we apply the Cauchy--Schwarz inequality to obtain
\begin{align*}
    \abstemp{B_\gamma(w,v)}&\leq \int_\Omega \abstemp{\gamma(x)}\abstemp{\nabla w(x)}\abstemp{\nabla v(x)}\dd{x}\\
    &\leq M\normtemp{\nabla w}_{L^2(\Omega)}\normtemp{\nabla v}_{L^2(\Omega)}\\
    &\leq M\normtemp{w-z\mathds{1}}_{H^1(\Omega)}\normtemp{v-z\mathds{1}}_{H^1(\Omega)}
\end{align*}
for any $z\in\mathbb{C}$ and any $w$ and $v$ in $H^1(\Omega)/\mathbb{C}$. The previous display implies that
\begin{align*}
    \abstemp{B_\gamma(w,v)}\leq M \normtemp{w}_{H^1(\Omega)/\mathbb{C}}\normtemp{v}_{H^1(\Omega)/\mathbb{C}}\,,
\end{align*}
which is the desired continuity.

By the Poincar\'e--Wirtinger inequality \cite[Remark~1, p.~376]{hanke2011convex},
\begin{align*}
    B_\gamma(v,v)=\int_\Omega \gamma(x)\abstemp{\nabla v(x)}^2\dd{x}
    \geq m \normtemp{\nabla v}^2_{L^2(\Omega)}
    \geq Cm\normtemp{v}^2_{H^1(\Omega)/\mathbb{C}}\,.
\end{align*}
This furnishes coercivity of $B_\gamma$.

To conclude, we bound the operator norm of the conjugate linear functional $f_{\gamma,g}$. Since $\overline{\Omega'}\subset \Omega$, it holds that $\Omega=(\Omega\setminus\Omega')\cup\Omega'$. Thus,
\begin{align*}
    -f_{\gamma,g}(v)=\int_{\Omega\setminus\Omega'} \nabla u_{\mathds{1},g}\cdot \overline{\nabla v}\dd{x} + \int_{\Omega'}\gamma\nabla u_{\mathds{1},g}\cdot \overline{\nabla v}\dd{x}
\end{align*}
because $\gamma\equiv 1$ on $\Omega\setminus\Omega'$. Since $\int_{\partial\Omega}g\dd{x}=0$ and $ u_{\mathds{1},g}\in H^1(\Omega)/\mathbb{C} $ solves the Neumann Laplace equation inside $\Omega$, we deduce that $\int_{\Omega} \nabla u_{\mathds{1},g}\cdot \overline{\nabla v}\dd{x}=0$. Therefore,
\begin{align*}
    \int_{\Omega\setminus\Omega'} \nabla u_{\mathds{1},g}\cdot \overline{\nabla v}\dd{x}&=
    \int_{\Omega} \nabla u_{\mathds{1},g}\cdot \overline{\nabla v}\dd{x}
    - \int_{\Omega'} \nabla u_{\mathds{1},g}\cdot \overline{\nabla v}\dd{x}\\
    &=-\int_{\Omega'} \nabla u_{\mathds{1},g}\cdot \overline{\nabla v}\dd{x}\,.
\end{align*}
Using the previous display, we now estimate
\begin{align*}
    \abstemp{f_{\gamma,g}(v)}&=\abstemp[\bigg]{\int_{\Omega'} \bigl(1-\gamma(x)\bigr)\nabla u_{\mathds{1},g}(x)\cdot \overline{\nabla v}(x) \dd{x}}\\
    &\leq \normtemp{\mathds{1}-\gamma}_{L^\infty(\Omega)}\normtemp{\nabla u_{\mathds{1},g}}_{L^2(\Omega')}\normtemp{\nabla v}_{L^2(\Omega')}\\
    &\leq (1+M)\normtemp{u_{\mathds{1},g}}_{H^1(\Omega')/\mathbb{C}}\normtemp{v}_{H^1(\Omega)/\mathbb{C}}\,.
\end{align*}
We used an argument similar to the one showing the continuity of $B_\gamma$. It follows that the operator norm $\normtemp{f_{\gamma,g}}_*$ of $f_{\gamma,g}$ is bounded above by $(1+M)\normtemp{u_{\mathds{1},g}}_{H^1(\Omega')/\mathbb{C}}$.

By interior harmonic regularity \cite[Lemma~22, p.~197, applied with exponents $1$ and $s+3/2$]{abraham2019statistical},
\begin{align*}
    \normtemp{u_{\mathds{1},g}}_{H^{1}(\Omega')/\mathbb{C}}\leq C_s \normtemp{u_{\mathds{1},g}}_{H^{s+3/2}(\Omega)/\mathbb{C}}\,.
\end{align*}
Again by \cite[Chp. 2, Remark 7.2, pp.~188--189]{lions2012non}, it holds that
\begin{align*}
    \normtemp{u_{\mathds{1},g}}_{H^{s+3/2}(\Omega)/\mathbb{C}}\leq C_s' \normtemp{g}_{H^s(\partial\Omega)}=C_s' \normtemp{g}_{{H}_\diamond^s(\partial\Omega)}\,.
\end{align*}
The equality of norms holds by \cite[Remark~(iii), p.~193]{abraham2019statistical}. Hence, $\normtemp{f_{\gamma,g}}_*\leq C_s'' (1+M) \normtemp{g}_{{H}_\diamond^s(\partial\Omega)}<\infty$. The Lax--Milgram theorem \cite[Thm.~1, Sec.~6.2.1, pp.~297--298]{evans1998partial} asserts the existence of a unique $w_{\gamma,g}\in H^1(\Omega)/\mathbb{C}$ solving \eqref{eqn:weak_neumann_temp}. In particular, $B_\gamma(w_{\gamma,g},w_{\gamma,g})=f_{\gamma,g}(w_{\gamma,g})$. This equality, the operator norm bound on $f_{\gamma,g}$, and the coercivity of $B_\gamma$ imply \eqref{eqn:uniform_w_continuity_bound} as required.

