	\begin{align*}
		w\coloneqq u_{\gamma,g}-u_{\mathds{1},g}\,,
	\end{align*}
	where $u_{\gamma,g}$ solves \eqref{eqn:elliptic} with fixed but arbitrary conductivity $\gamma$ and $u_{\mathds{1},g}$ solves \eqref{eqn:elliptic} with $\gamma\equiv 1$ (i.e., the Laplace equation). In the following, it will be important to recognize that
	\begin{align*}
		\Delta w=0 \quad\text{on}\quad \Omega\setminus \Omega'
	\end{align*}
	because $\gamma\equiv 1$ on $\Omega\setminus \Omega'$. Thus, $w=w_{\gamma,g}$ is also harmonic on the domain $\Omega\setminus\overline{D}\subset \Omega\setminus \Omega'$. This fact will allow us to control the dependence of constants on $\gamma$.

	Let $t\in\mathbb{R}$. We begin by estimating the boundary traces of $w$. To this end, we first note by \Cref{lem:app_boundary}~\ref{item:lem_bdry1} that ${\partial\Omega}\subseteq \partial(\Omega\setminus\overline{D})$ because $\overline{D}\subseteq\Omega$. Thus, $\normtemp{w}_{H^t({\partial\Omega})/\mathbb{C}}\leq C\normtemp{w}_{H^t(\partial(\Omega\setminus\overline{D}))/\mathbb{C}}$ by monotonicity and the norm equivalence of the spectral (recall Eqn.~\ref{eqn:defn_boundary_sobolev_spectral}) and interpolation definitions of fractional Sobolev norms on compact boundary manifolds 
	\cite[Chp.~1, Sec.~7.3, pp.~34--37]{lions2012non}.

	Next, for any $z\in\mathbb{C}$, we apply appropriate boundary trace theorems to the harmonic function $w-z\mathds{1}$ to obtain
	\begin{align*}
		\normtemp{w}_{H^t(\partial(\Omega\setminus\overline{D}))/\mathbb{C}}\leq \normtemp{w-z\mathds{1}}_{H^t(\partial(\Omega\setminus\overline{D}))}\leq C \normtemp{w-z\mathds{1}}_{H^{t+1/2}(\Omega\setminus\overline{D})}\,.
	\end{align*}
	For $t>0$, the preceding result follows from \cite[Chp.~1, Thm.~9.4, pp.~41--42, taking $\mu=0$ and $s=t+1/2$]{lions2012non}. For $t\leq -1/2$, we invoke \cite[Chp.~2, Thm.~6.5 and Remark 6.4, pp.~175--177, taking $m=1$, $m_0=0$, $r=-t-1/2$, and $A=-\Delta$]{lions2012non}. The final case $-1/2<t\leq 0$ is due to \cite[Chp.~2, Thm.~7.3, pp.~187--188, taking $m=1$, $m_0=0$, $0<s=t+1/2<2$, and $A=-\Delta$]{lions2012non}. Taking the infimum over $z\in\mathbb{C}$ in the previous display delivers the bound
	\begin{align*}
		\normtemp{w}_{H^t(\partial(\Omega\setminus\overline{D}))/\mathbb{C}}\leq C \normtemp{w}_{H^{t+1/2}(\Omega\setminus\overline{D})/\mathbb{C}}\,.
	\end{align*}

	To bound the right hand side from above in the last display, we use stability bounds for the solution operator of the Neumann problem applied to the Laplace  equation on the domain $\Omega\setminus\overline{D}$. First, since the boundary of a set equals the boundary of its complement,
	\begin{align*}
		\partial(\Omega\setminus\overline{D}) = \partial(\Omega \cap (\overline{D})^\textsf{c})=\partial(\Omega^\textsf{c}\cup \overline{D}) \subseteq \partial \Omega \cup \partial \overline{D}\subseteq \partial \Omega \cup \partial D\,.
	\end{align*}
	The first inclusion follows from $\partial(A\cup B)\subseteq \partial A\cup \partial B$ and the second from $\partial\overline{A}\subseteq \partial A$ for any sets $A$ and $B$ in a metric space. Next, application of \cite[Chp.~2, Remark 7.2, pp.~188--189, taking $\Omega=\Omega\setminus\overline{D}$, $A=-\Delta$, $f\equiv 0$, $s=t+1/2$, $m=m_0=1$, and $N=\{z\mathds{1}\colon z\in\mathbb{C}\}$]{lions2012non} and the monotonicity implied by the previous display deliver the bounds
	\begin{align*}
		\normtemp{w}_{H^{t+1/2}(\Omega\setminus\overline{D})/\mathbb{C}}&\leq C \normtemp[\bigg]{\frac{\partial w}{\partial\mathsf{n}}}_{H^{t-1}(\partial(\Omega\setminus\overline{D}))}\\
		&\leq C\mathopen{}\mathclose\bgroup\originalleft(\normtemp[\bigg]{\frac{\partial w}{\partial\mathsf{n}}}_{H^{t-1}(\partial\Omega)} + \normtemp[\bigg]{\frac{\partial w}{\partial\mathsf{n}}}_{H^{t-1}(\partial D)}\aftergroup\egroup\originalright)\\
		&= C\normtemp[\bigg]{\frac{\partial w}{\partial\mathsf{n}}}_{H^{t-1}(\partial D)}\,.
	\end{align*}
	The equality in the final line holds because the Neumann data satisfies 
	\begin{align*}
		\frac{\partial w}{\partial\mathsf{n}}=\frac{\partial u_{\gamma,g}}{\partial\mathsf{n}}-\frac{\partial u_{\mathds{1},g}}{\partial\mathsf{n}}=g-g=0 \quad\text{on}\quad {\partial\Omega}\,.
	\end{align*}
	Next, we bound the Neumann data by the interior solution. Let $S\coloneqq D\cap U$. Since $\partial D\subseteq U$ by construction, \cref{lem:app_boundary}~\ref{item:lem_bdry2} implies that 
	\begin{align*}
		\partial S=\partial(D\cap U)\supseteq (U\cap\partial D)\cup(D\cap\partial U)=\partial D \cup(D\cap\partial U)\supseteq \partial D\,.
	\end{align*}
	Similar application of boundary trace theorems to the domain $S\subseteq U$ leads to
	\begin{align*}
		\normtemp[\bigg]{\frac{\partial w}{\partial\mathsf{n}}}_{H^{t-1}(\partial D)} = \normtemp[\bigg]{\frac{\partial (w-z\mathds{1})}{\partial\mathsf{n}}}_{H^{t-1}(\partial D)}
		&\leq C \normtemp[\bigg]{\frac{\partial (w-z\mathds{1})}{\partial\mathsf{n}}}_{H^{t-1}(\partial S)}\\
		&\leq C \normtemp{w-z\mathds{1}}_{H^{t+1/2}(S)}\\
		&\leq C \normtemp{w-z\mathds{1}}_{H^{t+1/2}(U)}
	\end{align*}
	for any $z\in\mathbb{C}$. For $t>1$, \cite[Chp.~1, Thm.~9.4, pp.~41--42, taking $\mu=1$, $m=1$, and $s=t+1/2$]{lions2012non} gives the second inequality. The case $t\leq -1/2$ follows from \cite[Chp.~2, Thm.~6.5 and Remark 6.4, pp.~175--177, taking $m=1$, $m_0=1$, $r=-t-1/2$, and $A=-\Delta$]{lions2012non}. Finally, the inequality holds for $-1/2<t\leq 1$ by \cite[Chp.~2, Thm.~7.3, pp.~187--188, taking $m=1$, $m_0=1$, $0<s=t+1/2<2$, and $A=-\Delta$]{lions2012non}.

	Continuing, we use the preceding display and the interior regularity of harmonic functions \cite[Lemma~22, p.~197]{abraham2019statistical} to yield
	\begin{align*}
		\normtemp[\bigg]{\frac{\partial w}{\partial\mathsf{n}}}_{H^{t-1}(\partial D)}\leq C \normtemp{w}_{H^{t+1/2}(U)/\mathbb{C}}
