	\end{align*}
	Use of the generalized Lax--Milgram result from \cref{lem:lax_milgram_general} delivers the upper bound
	\begin{align*}
		\normtemp{w}_{H^1(\Omega)/\mathbb{C}}\leq \normtemp{w}_{H^1(\Omega)}\leq C_s\frac{M}{m}\normtemp{g}_{{H}_\diamond^s(\partial\Omega)}
	\end{align*}
	for a constant $C_s$ that is independent of the conductivity $\gamma$.

    Putting together the pieces gives
