\label{lem:app_boundary}
	Let $(X, \mathsf{d})$ be a metric space and $A\subseteq X$ and $B\subseteq X$ be subsets. The following holds true.
	\begin{enumerate}[label=(\roman*)]
		\item If $\overline{B}\subseteq \mathrm{Int}(A)$, then $\partial A\subseteq \partial(A\setminus B)$.\label{item:lem_bdry1}

		\item If $A$ and $B$ are both open in $(X, \mathsf{d})$, then $(A\cap\partial B)\cup (\partial A\cap B)\subseteq \partial(A\cap B)\setminus (\partial A\cap\partial B)$.\label{item:lem_bdry2}
	\end{enumerate}

We begin with \cref{item:lem_bdry1}. By definition of boundary and by basic set operations,
\begin{align*}
	\partial A &=\overline{A^\textsf{c}}\cap \overline{A}\\
	&\subseteq \overline{A^\textsf{c}}\\
	&\subseteq \overline{A^\textsf{c}}\cup\overline{B}\\
	&=\overline{A^\textsf{c}\cup B}\\
	&=\overline{(A\cap B^\textsf{c})^\textsf{c}}\\
	&=\overline{(A\setminus B)^\textsf{c}}\,.
\end{align*}
Moreover, $A=(A\setminus B)\cup (A\cap B)\subseteq (A\setminus B)\cup B$. Therefore,
\begin{align*}
	\partial A &=\overline{A^\textsf{c}}\cap \overline{A}\\
	&\subseteq \overline{A^\textsf{c}}\cap \overline{(A\setminus B)\cup B}\\
	& = \overline{A^\textsf{c}}\cap\bigl(\overline{A\setminus B} \cup \overline{B}\bigr)\\
	&= \bigl(\overline{A^\textsf{c}}\cap \overline{A\setminus B}\bigr) \cup \bigl(\overline{A^\textsf{c}}\cap\overline{B}\bigr)\\
	&\subseteq \bigl(\overline{A\setminus B}\bigr) \cup \bigl(\overline{A^\textsf{c}}\cap\overline{B}\bigr)\,.
\end{align*}
By the hypothesis $\overline{B}\subseteq \mathrm{Int}(A)$, it holds that $\overline{A^\textsf{c}}\cap\overline{B}\subseteq \overline{A^\textsf{c}}\cap \mathrm{Int}(A) = \emptyset$. Thus, $\partial A\subseteq \overline{A\setminus B}$. It follows that $\partial A\subseteq \overline{A\setminus B} \cap \overline{(A\setminus B)^\textsf{c}}=\partial(A\setminus B)$ as asserted in \cref{item:lem_bdry1}.

Next, we prove \cref{item:lem_bdry2} under the hypothesis that $A$ and $B$ are open. By symmetry, it suffices to prove that $(A\cap\partial B)\subseteq \partial(A\cap B)\setminus (\partial A\cap\partial B)$. If $x\in A\cap\partial B$, then $x\in A$. Thus, $x\notin\partial A=\overline{A}\setminus\mathrm{Int}(A)$ because $A=\mathrm{Int}(A)$ is open. We have shown that $x\notin (\partial A\cap\partial B)$. It remains to show that $x\in\partial(A\cap B)$. By the first part of the proof of \cref{item:lem_bdry1}, it holds that
\begin{align*}
	A\cap\partial B=A\cap \overline{B}\cap\overline{B^\textsf{c}}\subseteq \overline{B^\textsf{c}}\subseteq \overline{(B\cap S)^\textsf{c}}
\end{align*}
for any set $S$. In particular, taking $S=A$ gives $x\in \overline{(A\cap B)^\textsf{c}}$. By the second part of the proof of \cref{item:lem_bdry1}, for any set $T$ it holds that
\begin{align*}
	\partial B = \overline{B^\textsf{c}}\cap \overline{B}\subseteq  \overline{B^\textsf{c}}\cap\overline{(B\setminus T)\cup T}= (\overline{B^\textsf{c}} \cap \overline{B\setminus T}) \cup (\overline{B^\textsf{c}} \cap \overline{T})\,.
\end{align*}
Thus, $A\cap \partial B\subseteq (A\cap \overline{B^\textsf{c}} \cap \overline{B\setminus T}) \cup (\overline{B^\textsf{c}} \cap \overline{T}\cap A)$. The choice $T=A^\textsf{c}$ and the fact that $A^\textsf{c}$ is closed yield the set inclusions
\begin{align*}
	A\cap \partial B& \subseteq (A\cap \overline{B^\textsf{c}} \cap \overline{B\setminus A^\textsf{c}}) \cup (\overline{B^\textsf{c}} \cap A^\textsf{c} \cap A)\\
	&= (A\cap \overline{B^\textsf{c}} \cap \overline{A\cap B}) \cup (\overline{B^\textsf{c}} \cap \emptyset)\\
	& = (A\cap \overline{B^\textsf{c}} \cap \overline{A\cap B})\\
	&\subseteq \overline{A\cap B}\,.
\end{align*}
We deduce that $x\in \overline{A\cap B}\cap \overline{(A\cap B)^\textsf{c}} = \partial (A\cap B)$ as required.

