	\begin{align}
		\normtemp{T}_{\mathrm{HS}(H^r_\diamond({\partial\Omega});H^s({\partial\Omega})/\mathbb{C})}\leq C \normtemp{T}_{\mathscr{L}(H^{p-(d-1)}_\diamond({\partial\Omega});H_{\phantom{\diamond}}^q({\partial\Omega})/\mathbb{C})}\,.
	\end{align}
    Additionally, for any $J\in\mathbb{N}$ and $K\in\mathbb{N}$, it holds that
