        &\qquad\qquad\qquad\qquad \leq C' \normtemp{T}_{\mathscr{L}(H^{p-(d-1)}_\diamond({\partial\Omega});H_{\phantom{\diamond}}^q({\partial\Omega})/\mathbb{C})}\max\Bigl(J^{-\bigl(\frac{r-p}{d-1}\bigr)}, K^{-\bigl(\frac{q-s}{d-1}\bigr)}\Bigr)\,.\notag
    \end{align}

